// Thin wrapper over the Wails bindings (frontend/wailsjs, generated by `wails generate module`).
import * as App from '~/wailsjs/go/main/App'
import { EventsOn } from '~/wailsjs/runtime/runtime'

export const api = App as any
export const onEvent = (name: string, f: (...a: any[]) => void) => EventsOn(name, f)
